import{z as n,x as o,o as e,c as m,q as s,j as l,D as E,d as A,s as r,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"SARSA 与 Q 学习","description":"","frontmatter":{"title":"SARSA 与 Q 学习","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sarsa-q-learning.md","filePath":"llm/sarsa-q-learning.md","lastUpdated":1791063341000}'),_={name:"llm/sarsa-q-learning.md"};function d(p,a,C,S,D,F){const B=o("Mermaid");return e(),m("div",null,[a[2]||(a[2]=s('<h1 id="sarsa-与-q-学习" tabindex="-1">SARSA 与 Q 学习 <a class="header-anchor" href="#sarsa-与-q-学习" aria-label="Permalink to &quot;SARSA 与 Q 学习&quot;">​</a></h1><div class="epigraph"><p>同策略先承认「我接下来大概会乱走」，离策略直接假设「下一步必然最优」；max 的乐观会把估计误差记成价值。</p><footer>—— 据 Sutton &amp; Barto, 2018, 第 6 章；Watkins, Learning from Delayed Rewards, 1989 整理</footer></div><p><a href="/llm/td-zero-bootstrapping">上一课</a>把学习信号写成 TD 误差，但评估的对象仍是给定策略的 \\(v_\\pi\\)；评估只是控制的一半，另一半是改进——按价值给动作排序需要 \\(q_\\pi\\)（定义见<a href="/llm/return-discounting">回报、折扣与价值函数</a>），改进的探索端由 <a href="/llm/exploration-epsilon">ε-贪婪与乐观初始化</a>供给。缺口在于：把自举搬到 \\((s,a)\\) 上时，目标里的「下一个动作」取谁，会把算法劈成两族。本课写 SARSA 与 Q 学习，以及 max 算子带来的系统性过估计。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TD 思想平移到 \\((s,a)\\)：状态的后继是状态，状态-动作对的后继是「下一状态加下一动作」。SARSA 取行为策略<strong>实际会选</strong>的 \\(a&#39;\\)：目标 \\(r_{t+1}+\\gamma Q(s_{t+1},a_{t+1})\\)，名字来自五元组 State-Action-Reward-State-Action。Q 学习（Watkins 1989）取「无论实际做什么，都假设下一步最优」：目标 \\(r_{t+1}+\\gamma\\max_{a&#39;}Q(s_{t+1},a&#39;)\\)。一个对 \\(q_\\pi\\) 自举、评估的就是那个含探索的自己（同策略）；一个对 \\(q_*\\) 自举、行为与目标脱钩（离策略）。差别浓缩成目标里的一个算子：\\(Q(s&#39;,a&#39;)\\) 还是 \\(\\max_{a&#39;}Q(s&#39;,\\cdot)\\)。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>SARSA 更新：</p> \\[Q(s_t,a_t)\\leftarrow Q(s_t,a_t)+\\alpha\\big[r_{t+1}+\\gamma Q(s_{t+1},a_{t+1})-Q(s_t,a_t)\\big] \\]<p>\\(a_{t+1}\\) 必须真的按当前 ε-贪婪策略采出来再进公式——学到的价值因此含探索的代价。Q 学习把目标里的 \\(Q(s_{t+1},a_{t+1})\\) 换成 \\(\\max_{a&#39;}Q(s_{t+1},a&#39;)\\)：行为策略可以随便探索，学习目标始终贪心。两者的收敛账都在表格、覆盖与衰减步长下成立：Q 学习收敛到 \\(q_*\\)（Watkins &amp; Dayan 1992），SARSA 配合 ε 递减到最优。</p>',9)),(e(),l(i,null,{default:E(()=>[r(B,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20TR%5B%22%E5%8F%96%E5%BE%97%E8%BD%AC%E7%A7%BB%20(s%2C%20a%2C%20r%2C%20s%E2%80%B2)%22%5D%20--%3E%20SAR%5B%22SARSA%EF%BC%9A%E7%9B%AE%E6%A0%87%20r%20%2B%20%CE%B3Q(s%E2%80%B2%2C%20a%E2%80%B2)%EF%BC%8Ca%E2%80%B2%20%E6%8C%89%E8%A1%8C%E4%B8%BA%E7%AD%96%E7%95%A5%E5%AE%9E%E9%87%87%22%5D%0A%20%20TR%20--%3E%20QL%5B%22Q%20%E5%AD%A6%E4%B9%A0%EF%BC%9A%E7%9B%AE%E6%A0%87%20r%20%2B%20%CE%B3%20max%20Q(s%E2%80%B2%2C%20%C2%B7)%22%5D%0A%20%20SAR%20--%3E%20ON%5B%22%E5%90%8C%E7%AD%96%E7%95%A5%EF%BC%9A%E8%AF%84%E4%BC%B0%E5%90%AB%E6%8E%A2%E7%B4%A2%E7%9A%84%E8%87%AA%E5%B7%B1%22%5D%0A%20%20QL%20--%3E%20OFF%5B%22%E7%A6%BB%E7%AD%96%E7%95%A5%EF%BC%9A%E8%A1%8C%E4%B8%BA%E4%BB%BB%E6%84%8F%EF%BC%8C%E7%9B%AE%E6%A0%87%E8%B4%AA%E5%BF%83%22%5D%0A%20%20ON%20--%3E%20IMP%5B%22%CE%B5-%E8%B4%AA%E5%A9%AA%E6%94%B9%E8%BF%9B%EF%BC%8C%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20OFF%20--%3E%20IMP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[A("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,[A("max 的代价是一条不等式：对任意带噪声的估计，\\(\\mathbb{E}[\\max_a X_a]\\ge\\max_a\\mathbb{E}[X_a]\\)——挑最大时总把误差的最大份也挑了进去，高估是系统性的，动作越多挑得越狠；转移与奖励的噪声越大越重。Double Q 学习（van Hasselt 2010）把「挑」与「评」拆到两套表格上，一套选、另一套评，是这条病的直接修法。同策略那一侧不是缺陷而是如实记账：Sutton & Barto §6.5 的 Cliff Walking（ε=0.1）里，Q 学习学出贴崖最短路，执行时 ε 一抖就坠崖，期均回报反而差；SARSA 学出绕开悬崖的安全路——它知道自己会乱走。"),t("span",{class:"marginnote"},"数字实例：两个动作真值都是 0，估计各带 ±1 的对称噪声。max 之后期望变成 0.5（3/4 的概率挑到 +1 那条）——尽管两个动作实际一样好。真值相同的候选越多，max 挑出的正偏差越大，这就是那条不等式的具体样子。")],-1)),(e(),l(i,null,{default:E(()=>[r(B,{id:"mermaid-30",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%5B%22%E6%AF%8F%E6%9D%A1%20Q(s%2Ca)%20%E4%BC%B0%E8%AE%A1%E5%90%AB%E9%9A%8F%E6%9C%BA%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20M%5B%22%E7%9B%AE%E6%A0%87%E5%8F%96%20max%3A%20%E6%8C%91%E4%B8%AD%E7%9A%84%E5%B8%B8%E6%98%AF%E8%AF%AF%E5%B7%AE%E4%B8%BA%E6%AD%A3%E6%9C%80%E5%A4%A7%E7%9A%84%E9%82%A3%E6%9D%A1%22%5D%0A%20%20M%20--%3E%20O%5B%22%E8%AF%AF%E5%B7%AE%E6%BB%9A%E8%BF%9B%E8%87%AA%E4%B8%BE%2C%20%E7%B3%BB%E7%BB%9F%E6%80%A7%E9%AB%98%E4%BC%B0%22%5D%0A%20%20O%20--%3E%20W%5B%22%E5%8A%A8%E4%BD%9C%E6%95%B0%E8%B6%8A%E5%A4%9A%2C%20%E6%8C%91%E5%88%B0%E5%9D%8F%E8%AF%AF%E5%B7%AE%E7%9A%84%E6%9C%BA%E4%BC%9A%E8%B6%8A%E5%A4%A7%22%5D%0A%20%20E%20--%3E%20F%5B%22Double%20Q%3A%20%E4%B8%A4%E5%A5%97%E8%A1%A8%2C%20A%20%E8%A1%A8%E6%8C%91%E5%8A%A8%E4%BD%9C%2C%20B%20%E8%A1%A8%E7%BB%99%E8%AF%84%E4%BB%B7%22%5D%0A%20%20F%20--%3E%20G%5B%22%E6%8C%91%E4%B8%8E%E8%AF%84%E8%A7%A3%E8%80%A6%2C%20%E9%AB%98%E4%BC%B0%E8%A2%AB%E6%8A%B5%E6%B6%88%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=s('<p><span class="marginnote">Cliff Walking 的口径：起点到终点之间一条紧贴悬崖的捷径，每步奖励 −1，坠崖 −100 并送回起点。ε=0.1 时 SARSA 的安全路是「含探索代价的最优」，不是胆小。</span></p><p>对 LLM 埋两条线。其一，<a href="/llm/llm-decision-view">语言生成作为 MDP</a> 已指出动作是几万到几十万的词表：表格 \\(Q\\) 写不下，逐动作 \\(\\max\\) 也扫不动，函数逼近不可回避——它将在致命三要素处回来。其二，Q 学习的「离策略」只到目标为止，数据仍由自己生成；当数据干脆来自别的策略（旧版本模型的 rollout、重放池），分布差要重要性采样校正——下一课。<span class="marginnote">「离策略」可理解成「拿别人的错题本学习」：要学的目标（那套贪心标准）不变，数据可以来自旧版本模型或重放池；SARSA 则是「自己边走边学」，走姿（含探索的 ε）本身写进了账本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>过估计在小而确定的网格上几乎看不见，要在实验课里专门加噪声才能复现——「没见过高估」不等于「max 无罪」。SARSA 的安全相对执行策略而言：换成更贪心的执行，账本作废。两者的收敛都要求每对 \\((s,a)\\) 被无限次访问：离策略不豁免探索。Q 学习对 \\(q_*\\) 自举，等于把「最优性」假设写进目标；当真实环境的最优不是你想要的最优（奖励有洞），它学得比谁都快。<span class="marginnote">常见误区：以为「Q 学习学出最短路」就一定更好。那是最优路径、无探索执行下的好；实际执行每步都有 ε 概率乱动，贴崖路径一抖就坠崖。比较两种算法前要先钉死执行时的探索水平，否则比较的是执行策略不是学习算法。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SARSA 对实际执行的下一动作自举（同策略）；Q 学习对 \\(\\max_{a&#39;}Q\\) 自举（离策略）。</li><li>差别浓缩为目标里的一个算子：\\(Q(s&#39;,a&#39;)\\) 还是 \\(\\max_{a&#39;}Q(s&#39;,\\cdot)\\)。</li><li>max 在噪声下系统性过估计，动作越多越重；Double Q 把挑与评拆开。</li><li>同策略学到的价值含探索代价；执行策略一换，账本作废。</li><li>词表尺度的动作空间逼出函数逼近，外来数据逼出重要性采样——两条线都在后课。</li><li>出处：Watkins 1989；Watkins &amp; Dayan 1992；van Hasselt 2010；Sutton &amp; Barto 2018 第 6 章。</li></ul>',6))])}const f=n(_,[["render",d]]);export{h as __pageData,f as default};
